const listEntriesForAPI = `-- name: ListEntriesForAPI :many

SELECT e.id, e.user_id, e.entry_type, e.scope, e.content, e.tags, e.service_id, e.asset_id, e.work_shift_id, e.glpi_ticket_id, e.glpi_linked_at, e.ticket_id, e.image_url, e.image_hash, e.image_size_bytes, e.created_at, e.updated_at, e.owner_complement_id, e.owner_complement_name, e.api_key_id, e.api_key_name, u.username AS author_username,
  COALESCE(COALESCE(so.id, ac.id, tc.id)::text, '')::text AS client_id, COALESCE(so.name, ac.name, tc.name, '')::text AS client_name
FROM entries e
JOIN users u ON u.id = e.user_id
LEFT JOIN services sv ON sv.id = e.service_id
LEFT JOIN organizations so ON so.id = sv.organization_id
LEFT JOIN assets ast ON ast.id = e.asset_id
LEFT JOIN organizations ac ON ac.id = ast.client_id
LEFT JOIN LATERAL (SELECT o.id, o.name FROM organizations o, unnest(e.tags) t WHERE lower(t) = lower('cliente:' || o.name) LIMIT 1) tc ON true
WHERE ($1::uuid IS NULL OR e.id = $1)
  AND ($2::uuid[] IS NULL OR COALESCE(so.id, ac.id, tc.id) = ANY($2::uuid[]))
  AND ($3::uuid IS NULL OR COALESCE(so.id, ac.id, tc.id) = $3)
  AND ($4::timestamptz IS NULL OR e.created_at >= $4)
  AND ($5::timestamptz IS NULL OR (e.created_at, e.id) < ($5::timestamptz, $6::uuid))
ORDER BY e.created_at DESC, e.id DESC
LIMIT $7
`

