func (q *Queries) ListTicketsForAPI(ctx context.Context, arg ListTicketsForAPIParams) ([]ListTicketsForAPIRow, error) {
	rows, err := q.db.Query(ctx, listTicketsForAPI,
		arg.ClientIds,
		arg.ClientID,
		arg.Status,
		arg.Since,
		arg.BeforeAt,
		arg.BeforeID,
		arg.MaxRows,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListTicketsForAPIRow
	for rows.Next() {
		var i ListTicketsForAPIRow
		if err := rows.Scan(
			&i.ID,
			&i.TicketNumber,
			&i.TicketType,
			&i.Scope,
			&i.ClientID,
			&i.AssetID,
			&i.ServiceID,
			&i.AssignedTeamID,
			&i.AssignedUserID,
			&i.AssignedContactID,
			&i.Status,
			&i.Impact,
			&i.Urgency,
			&i.Priority,
			&i.Title,
			&i.Description,
			&i.SlaResponseDueAt,
			&i.SlaResolutionDueAt,
			&i.SlaOnHoldSince,
			&i.SlaPausedSeconds,
			&i.FirstRespondedAt,
			&i.ResolvedAt,
			&i.ClosedAt,
			&i.ReopenedCount,
			&i.ReopenedAt,
			&i.PublicTrackingToken,
			&i.PublicTrackingEnabled,
			&i.PublicTrackingPin,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.ParentID,
			&i.MergedIntoID,
			&i.AffectsClient,
			&i.NotifyTo,
			&i.NotifyCc,
			&i.SlaResponseBreachNotifiedAt,
			&i.SlaResolutionWarnNotifiedAt,
			&i.SlaResolutionBreachNotifiedAt,
			&i.TerritorialUnitID,
			&i.AreaID,
			&i.RequestedAreaID,
			&i.Source,
			&i.GlpiID,
			&i.GlpiDateMod,
			&i.GlpiSyncedAt,
			&i.GlpiDeleted,
			&i.GlpiLinkedOnly,
			&i.GlpiGroupID,
			&i.GlpiGroupName,
			&i.GlpiTechnician,
			&i.ApiKeyID,
			&i.ApiKeyName,
			&i.ClientName,
			&i.AreaCode,
			&i.AreaName,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const markForwardFailed = `-- name: MarkForwardFailed :one
UPDATE forward_destinations SET failures = failures + 1, failing_since = COALESCE(failing_since, now()),
  last_error = $1, last_error_at = now(), next_attempt_at = $2
WHERE id = $3
RETURNING failing_since, down_alerted
`

type MarkForwardFailedParams struct {
	Error         pgtype.Text        `json:"error"`
	NextAttemptAt pgtype.Timestamptz `json:"next_attempt_at"`
	ID            uuid.UUID          `json:"id"`
}

type MarkForwardFailedRow struct {
	FailingSince pgtype.Timestamptz `json:"failing_since"`
	DownAlerted  bool               `json:"down_alerted"`
}

func (q *Queries) MarkForwardFailed(ctx context.Context, arg MarkForwardFailedParams) (MarkForwardFailedRow, error) {
	row := q.db.QueryRow(ctx, markForwardFailed, arg.Error, arg.NextAttemptAt, arg.ID)
	var i MarkForwardFailedRow
	err := row.Scan(&i.FailingSince, &i.DownAlerted)
	return i, err
}

const markForwardSent = `-- name: MarkForwardSent :one
UPDATE forward_destinations d SET cursor_id = GREATEST(d.cursor_id, $1), last_sent_at = now(),
  failures = 0, failing_since = NULL, next_attempt_at = NULL, down_alerted = false, last_error = NULL
FROM (SELECT p.down_alerted AS was_alerted FROM forward_destinations p WHERE p.id = $2) prev
WHERE d.id = $2
RETURNING prev.was_alerted
`

type MarkForwardSentParams struct {
	CursorID int64     `json:"cursor_id"`
	ID       uuid.UUID `json:"id"`
}

// Devuelve si estaba caído y ya se había avisado, para avisar que volvió.
func (q *Queries) MarkForwardSent(ctx context.Context, arg MarkForwardSentParams) (bool, error) {
	row := q.db.QueryRow(ctx, markForwardSent, arg.CursorID, arg.ID)
	var was_alerted bool
	err := row.Scan(&was_alerted)
	return was_alerted, err
}

