const updateForwardDestination = `-- name: UpdateForwardDestination :one
UPDATE forward_destinations d SET
  name = $1, transport = $2, host = $3, port = $4, url = $5,
  format = $6, batch = $7, send_audit = $8, audit_level = $9,
  send_entries = $10, send_escalation = $11, send_tickets = $12,
  ca_cert = $13, client_cert = $14, client_key_encrypted = $15,
  header_names = $16, headers_encrypted = $17,
  cursor_id = CASE WHEN $18::boolean AND NOT d.enabled THEN (SELECT COALESCE(max(fo.id), 0) FROM forward_outbox fo) ELSE d.cursor_id END,
  failures = CASE WHEN $18::boolean THEN d.failures ELSE 0 END,
  failing_since = CASE WHEN $18::boolean THEN d.failing_since END,
  down_alerted = CASE WHEN $18::boolean THEN d.down_alerted ELSE false END,
  next_attempt_at = NULL,
  enabled = $18, updated_at = now()
WHERE d.id = $19
RETURNING id, name, enabled, transport, host, port, url, format, batch, send_audit, audit_level, send_entries, send_escalation, send_tickets, ca_cert, client_cert, client_key_encrypted, header_names, headers_encrypted, cursor_id, lease_until, lease_owner, next_attempt_at, failures, failing_since, down_alerted, last_sent_at, last_error, last_error_at, created_by, created_at, updated_at
`

